/**
 * A column of items of one kind, each read, followed or picked (`design/components/list.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onCleanup, onMount, type JSX } from 'solid-js'

import {
  agentMember,
  chooseListItem,
  claimSlot,
  currentListItem,
  elementRef,
  listItems,
  scope,
} from '@polymorph/solid'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListProps {
  /**
   * `List.Item`s.
   */
  children?: JSX.Element
  /**
   * Names the list for a reader: "Notifications", not "List".
   */
  label: string
}

/** A column of items of one kind, each read, followed or picked. */
export default function List(given: ListProps): JSX.Element {
  const props = claimSlot(given)
  return scope(() => {
    const list = elementRef<HTMLElement>()
    let release1: (() => void) | undefined
    const effect1 = () => {
      release1?.()
      const ran = agentMember({
        member: 'List',
        element: () => list.value,
        state: () => ({
          items: listItems(list.value, styles.primary),
          current: currentListItem(list.value, styles.primary),
        }),
        actions: {
          choose: {
            argument: 'id',
            run: (value) => chooseListItem(list.value, styles.primary, value),
          },
        },
      })
      release1 = () => {
        ran()
      }
    }
    onMount(effect1)
    onCleanup(() => release1?.())
    return (
      <ul
        class={styles.list}
        role="list"
        aria-label={props.label}
        data-member="list"
        ref={list.attach}
      >
        {props.children}
      </ul>
    )
  })
}
